'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d}),pct=n=>n==null?'—':(n*100).toFixed(1)+'%';
let result=null,page='overview',inputText='',labelsText='',comparison=null,worker=null,seq=0,waiting=new Map(),backend=false,busy=false,source='sample',pageIndex=0,filter='test',search='',runtimeModel=false,currentRunKey='',inputKind='sample',inputName='',triageCache={},incidentFilter='all',incidentPage=0;
const titles={incidents:['Review the evidence.<br><span>Track the response.</span>','Assign an owner, capture investigation notes and track each flagged test window.'],overview:['See the signal.<br><span>Understand the anomaly.</span>','From raw system logs to explainable, window-level insights.'],windows:['Every window.<br><span>A story in the logs.</span>','Inspect evidence, features and the score behind each decision.'],templates:['Less noise.<br><span>More structure.</span>','Regex normalization, data quality and recurring event patterns.'],evaluation:['Measure honestly.<br><span>Compare carefully.</span>','Held-out window metrics, fixed-window baselines and experimental limits.']};
function status(message,error=false){$('status').textContent=message;$('status').className='status'+(error?' error':'')}
function metric(label,value,sub,glyph='↗',alert=false){return `<div class="metric ${alert?'alert':''}"><span class="glyph">${glyph}</span><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function card(title,subtitle,body,extra=''){return `<section class="card"><div class="card-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${extra}</div><div class="card-body">${body}</div></section>`}
function options(){return {dataset:$('dataset').value,mode:$('mode').value,fixed_seconds:+$('fixedSeconds').value,min_seconds:+$('minSeconds').value,max_seconds:+$('maxSeconds').value,target_logs:+$('targetLogs').value,train_fraction:+$('trainFraction').value,contamination:+$('contamination').value,trees:+$('trees').value,partitions:+$('partitions').value,seed:42}}
function setBusy(value){busy=value;document.querySelectorAll('.control-panel input,.control-panel select,.control-panel button').forEach(e=>{if(e.id!=='cancelBtn')e.disabled=value});$('historyBtn').disabled=value;document.querySelectorAll('[data-action="compare"],[data-action="model"],[data-action="parsed"],[data-restore]').forEach(e=>e.disabled=value);$('cancelBtn').classList.toggle('hidden',!value||backend);$('runBtn').innerHTML=value?'Processing…':'Run analysis <span>↗</span>';document.querySelector('main').setAttribute('aria-busy',String(value))}
function launchWorker(){worker=new Worker('./worker.js?v=3');worker.onmessage=({data})=>{if(data.type==='status'){status(data.message);return}const p=waiting.get(data.id);if(!p)return;waiting.delete(data.id);data.type==='error'?p.reject(Error(data.message)):p.resolve(data.result)};worker.onerror=e=>{for(const p of waiting.values())p.reject(Error(e.message||'Python worker failed. Please retry.'));waiting.clear();worker.terminate();worker=null}}
async function python(action,payload){if(!worker)launchWorker();const id=++seq;return new Promise((resolve,reject)=>{waiting.set(id,{resolve,reject});worker.postMessage({id,action,payload})})}
async function api(path,body){const headers={'Content-Type':'application/json'},token=sessionStorage.getItem('logscope-token');if(token)headers.Authorization='Bearer '+token;const response=await fetch(path,{method:body?'POST':'GET',headers,body:body?JSON.stringify(body):undefined});if(!response.ok){let e;try{e=await response.json()}catch{}throw Error((e?.error||`Request failed (${response.status})`)+(e?.request_id?' Reference: '+e.request_id:''))}return response}
function payload(action){if(!inputText.trim())throw Error('Load a dataset sample first.');const c=options();if(Object.values(c).some(v=>typeof v==='number'&&!Number.isFinite(v)))throw Error('All analysis settings must be valid numbers.');if(c.min_seconds<1||c.max_seconds<c.min_seconds||c.max_seconds>86400)throw Error('Window limits: 1 ≤ minimum ≤ maximum ≤ 86,400 seconds.');if(c.fixed_seconds<1||c.fixed_seconds>86400)throw Error('Initial/fixed duration must be 1–86,400 seconds.');if(!Number.isInteger(c.target_logs)||c.target_logs<5||c.target_logs>5000)throw Error('Target logs must be a whole number from 5 to 5,000.');if(!Number.isInteger(c.trees)||c.trees<20||c.trees>300||!Number.isInteger(c.partitions)||c.partitions<1||c.partitions>8)throw Error('Use 20–300 whole trees and 1–8 whole partitions.');if(c.train_fraction<.3||c.train_fraction>.8||c.contamination<.001||c.contamination>.3)throw Error('Training fraction must be 0.3–0.8; contamination 0.001–0.3.');return {action,text:inputText,labels:labelsText,options:c,input_name:inputName}}
async function execute(action){if(busy)return;let p;try{p=payload(action)}catch(e){status(e.message,true);return}setBusy(true);status('Preparing analysis…');try{if(action==='compare'){comparison=backend?await(await api('/api/compare',p)).json():await python('compare',p);runtimeModel=false;page='evaluation';render();status('Comparison complete. Different window boundaries produce different evaluation units.')}else{const next=backend?await(await api('/api/analyze',p)).json():await python('analyze',p);next.client={input_name:inputName,input_kind:inputKind,created_at:next.created_at||new Date().toISOString(),release:'1.1.0'};result=next;runtimeModel=true;comparison=null;source='fresh';currentRunKey=result.run_id||crypto.randomUUID();triageCache={};const saved=await saveHistory(result,currentRunKey);pageIndex=0;await refreshTriage();render();$('provenance').textContent=`Fresh analysis · ${result.dataset} · ${num(result.timing.total_seconds,2)}s · ${backend?'Stored on configured Flask server':'Computed on this device'}`;status(saved===false?'Analysis complete, but history could not be saved. Download Results JSON now.':'Analysis complete. Review the held-out results, then triage flagged windows.',saved===false)}}catch(e){status(e.message,true)}finally{setBusy(false)}}
function curve(windows,field='score',threshold=null){const W=760,H=230,L=36,R=14,T=20,B=34,values=windows.map(w=>field==='score'?w.score:w.duration),max=field==='score'?1:Math.max(...values,1),x=i=>L+i/Math.max(values.length-1,1)*(W-L-R),y=v=>H-B-v/max*(H-T-B);let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${field==='score'?'Global anomaly scores':'Adaptive window durations'} across chronological test windows">`;for(let k=0;k<=4;k++){let v=k*max/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e9ede6"/><text x="${L-8}" y="${y(v)+3}" text-anchor="end" class="chart-label">${v.toFixed(field==='score'?2:0)}</text>`}const points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');svg+=`<polygon points="${L},${H-B} ${points} ${x(values.length-1)},${H-B}" fill="#e4eee5"/><polyline points="${points}" fill="none" stroke="#507b62" stroke-width="1.7"/>`;if(threshold!=null)svg+=`<line x1="${L}" x2="${W-R}" y1="${y(threshold)}" y2="${y(threshold)}" stroke="#c6884e" stroke-dasharray="5 5"/><text x="${W-R}" y="${Math.max(12,y(threshold)-6)}" text-anchor="end" class="chart-label">threshold ${threshold.toFixed(3)}</text>`;if(field==='score')windows.forEach((w,i)=>{if(w.anomaly)svg+=`<circle cx="${x(i)}" cy="${y(w.score)}" r="3.5" fill="#c17c49"><title>Window ${w.id}: ${w.score.toFixed(3)}</title></circle>`});svg+=`<text x="${L}" y="${H-8}" class="chart-label">Window ${windows[0]?.id??''}</text><text x="${W-R}" y="${H-8}" text-anchor="end" class="chart-label">Window ${windows.at(-1)?.id??''}</text></svg>`;return svg}
function testWindows(){return result.windows.filter(w=>w.split==='test')}
function overview(){const s=result.summary,test=testWindows(),dur=test.map(w=>w.duration),alerts=test.filter(w=>w.anomaly).sort((a,b)=>b.score-a.score).slice(0,5);return `<div class="metrics">${metric('Logs processed',num(s.total_logs),'Across '+num(s.total_windows)+' windows','≋')}${metric('Anomalous windows',num(s.anomalous_windows),pct(s.anomalous_windows/s.test_windows)+' of test windows','⚑',true)}${metric('Normal test windows',num(s.normal_windows),num(s.training_windows)+' windows reserved for training','✓')}${metric('Unique templates',num(s.unique_templates),result.quality.rejected_rows+' rejected input rows','⌘')}</div><div class="grid">${card('Anomaly signal','Global calibrated score · held-out windows only',curve(test,'score',s.threshold)+`<div class="chart-note"><span>${esc(s.start.slice(0,10))} → ${esc(s.end.slice(0,10))}</span><span>Higher score = more unusual</span></div>`,`<div class="legend"><span><i></i>Score</span><span><i class="orange"></i>Anomaly</span></div>`)}${card('Run at a glance','Your current experiment',`<div class="mini-stat"><span>Dataset</span><b>${esc(result.dataset)} / ${num(result.summary.total_logs)} logs</b></div><div class="mini-stat"><span>Window strategy</span><b>${esc(result.config.mode)}</b></div><div class="mini-stat"><span>Observed durations</span><b>${num(Math.min(...dur),1)}–${num(Math.max(...dur),1)}s</b></div><div class="mini-stat"><span>Isolation trees / partition</span><b>${result.config.trees}</b></div><div class="mini-stat"><span>Training / test split</span><b>${pct(result.config.train_fraction)} / ${pct(1-result.config.train_fraction)}</b></div><div class="mini-stat"><span>Analysis time</span><b>${num(result.timing.total_seconds,2)}s</b></div><div class="notice">${result.metrics?(result.metrics.single_class?'Normal-only sample: accuracy and false-positive rate available. Use the annotated OpenStack preset for association evaluation.':'Labeled evaluation available. See Evaluation for label provenance and classification metrics.'):'Ground-truth labels missing. Detection scores are available; F1 and recall are not.'}</div>`)}</div><section class="card wide-card"><div class="card-head"><div><h2>Priority windows</h2><p>Highest-scoring anomalies in the held-out segment</p></div><button class="link-button" data-nav="windows">Explore all windows →</button></div>${windowTable(alerts)}${!alerts.length?'<div class="empty">No test windows exceed the training-calibrated threshold.</div>':''}</section><div class="grid">${card('Window adaptation','Duration follows the previous arrival-rate estimate',curve(test,'duration'))}${card('Partition contribution','Local simulation · shared temporal boundaries',result.partitions.map(p=>`<div class="bar-label"><span>Partition ${p.partition+1}</span><b>${num(p.training_logs)} training logs</b></div><div class="bar-track"><div class="bar-fill" style="width:${p.training_logs/Math.max(...result.partitions.map(q=>q.training_logs),1)*100}%"></div></div><p class="caption">${esc(p.status)}</p>`).join('')+'<div class="notice">Scores are training-percentile calibrated, then weighted by training log count.</div>')}</div>`}
function windowTable(windows){return `<div class="table-wrap"><table><thead><tr><th>WINDOW / UTC</th><th>STATE</th><th>GLOBAL SCORE</th><th>LOGS</th><th>DURATION</th><th>LABEL</th><th></th></tr></thead><tbody>${windows.map(w=>`<tr><td><b>W${w.id}</b> <span class="pill ${w.split}">${w.split}</span><br><span class="mono">${esc(w.start.replace('T',' ').replace('Z',''))}</span></td><td><span class="pill ${w.severity}">${w.severity}</span></td><td><span class="score-track"><i style="width:${w.score*100}%"></i></span>${w.score.toFixed(3)}</td><td>${num(w.features.total_logs)}</td><td>${num(w.duration,1)}s</td><td>${w.label==null?'Unknown':w.label?'Anomaly':'Normal'}</td><td><button class="link-button" data-window="${w.id}">Inspect ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function filteredWindows(){return result.windows.filter(w=>(filter==='all'||filter===w.split||filter==='anomaly'&&w.split==='test'&&w.anomaly)&&(!search||('w'+w.id+' '+w.start+' '+w.examples.map(e=>e.message).join(' ')).toLowerCase().includes(search.toLowerCase())))}
function windowsPage(){const all=filteredWindows(),count=20;pageIndex=Math.min(pageIndex,Math.max(0,Math.ceil(all.length/count)-1));return `<section class="card"><div class="card-head"><div><h2>Window explorer</h2><p>Training decisions are diagnostic only; evaluation uses test windows.</p></div><div class="exports"><button class="secondary" data-action="csv">↓ Features CSV</button><button class="secondary" data-action="json">↓ Results JSON</button></div></div><div class="filters"><input id="windowSearch" placeholder="Search window ID, time or example message…" aria-label="Search windows" value="${esc(search)}"><select id="windowFilter" aria-label="Window filter">${[['test','Test windows'],['anomaly','Test anomalies'],['train','Training windows'],['all','All windows']].map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${l}</option>`).join('')}</select></div>${windowTable(all.slice(pageIndex*count,(pageIndex+1)*count))}${!all.length?'<div class="empty">No windows match these filters.</div>':''}<div class="pager"><span>${all.length?`${pageIndex*count+1}–${Math.min((pageIndex+1)*count,all.length)} of ${num(all.length)}`:'0 results'}</span><div class="row-actions"><button class="secondary" data-action="prev" ${!pageIndex?'disabled':''}>← Previous</button><button class="secondary" data-action="next" ${(pageIndex+1)*count>=all.length?'disabled':''}>Next →</button></div></div></section>`}
function templatesPage(){const q=result.quality,max=Math.max(...Object.values(result.eda.levels));return `<div class="metrics">${metric('Successfully parsed',num(q.parsed_rows),pct(q.parsed_rows/q.input_rows)+' parse success','✓')}${metric('Rejected rows',num(q.rejected_rows),'Malformed records are reported','≠')}${metric('Labeled logs',num(q.labels_available),'Verified input labels only','◉')}${metric('Templates',num(result.summary.unique_templates),'Deterministic regex normalization','≋')}</div><div class="grid">${card('Log-level distribution','Counts are descriptive; levels do not create ground truth',Object.entries(result.eda.levels).map(([k,v])=>`<div class="bar-label"><span>${esc(k)}</span><b>${num(v)}</b></div><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div>`).join(''))}${card('Data quality policy','Preserve evidence at every stage',`<div class="prose"><p>Logs are sorted chronologically. Repeated lines are retained because repetitions affect rates and counts.</p><p>Invalid timestamps or malformed fields are rejected with line numbers. Timezone-free input is interpreted as UTC.</p><p>Raw messages are retained alongside normalized templates.</p></div><button class="secondary" data-action="parsed">↓ Export parsed CSV</button>`)}</div><section class="card wide-card"><div class="card-head"><div><h2>Most frequent event templates</h2><p>Top 20 · counts across the full input, for exploratory analysis only</p></div></div><div class="table-wrap"><table><thead><tr><th>RANK</th><th>EVENT TEMPLATE</th><th>COUNT</th><th>SHARE</th></tr></thead><tbody>${result.eda.templates.map((t,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td class="mono">${esc(t.template)}</td><td>${num(t.count)}</td><td>${pct(t.count/q.parsed_rows)}</td></tr>`).join('')}</tbody></table></div></section>${q.rejects.length?card('Rejected input rows','First 100 failures',`<pre>${esc(JSON.stringify(q.rejects,null,2))}</pre>`):''}`}
function evaluationPage(){const m=result.metrics;const ev=result.evaluation;return `${ev?`<section class="card wide-card"><div class="card-head"><div><h2>${ev.provenance.label_kind==='derived_vm_association'?'VM-association evaluation':'Evaluation labels'}</h2><p>${num(ev.labeled_logs)} / ${num(ev.total_logs)} logs labeled · ${num(ev.positive_logs)} positive · ${num(ev.negative_logs)} negative</p></div></div><div class="card-body"><p class="prose">${esc(ev.provenance.note)}</p><p class="caption">${(ev.provenance.sources||[]).map(v=>`Source: ${esc(v.url)}`).join(' · ')}</p></div></section>`:''}<div class="metrics">${metric('Precision',m?pct(m.precision):'—','Correct / predicted anomalies','↗')}${metric('Recall',m?pct(m.recall):'—','Detected / actual anomalies','↗')}${metric('F1 score',m?.f1!=null?m.f1.toFixed(4):'—','Harmonic mean of precision & recall','≋')}${metric('False positive rate',m?pct(m.fpr):'—','False alerts / actual normal windows','⚑')}</div><div class="eval-grid">${card('Held-out evaluation',`${result.summary.test_windows} test windows · any-positive label · ${result.evaluation?.provenance?.label_kind==='derived_vm_association'?'VM association target':'verified input annotations'}`,m?`<div class="confusion"><div>TRUE POSITIVES<b>${m.tp}</b></div><div class="bad">FALSE POSITIVES<b>${m.fp}</b></div><div class="bad">FALSE NEGATIVES<b>${m.fn}</b></div><div>TRUE NEGATIVES<b>${m.tn}</b></div></div><div class="mini-stat"><span>Accuracy</span><b>${pct(m.accuracy)}</b></div><div class="notice">${m.single_class?'Only one class occurs in this test split. With no positive examples, precision/recall/F1 are withheld; accuracy, FPR and confusion counts remain available.':'These are measured sample results, including missed anomalies. They are not full-dataset benchmark claims.'}</div>`:'<div class="empty">Verified labels are missing.<br>Upload a label CSV in Configure to enable evaluation.</div><p class="caption">Supported: LineId,Label or HDFS BlockId,Label. Values: 0/1 or Normal/Anomaly. Every log in a test window needs a known label.</p>')}${card('Computational cost','Measured on this run’s execution environment',`<div class="mini-stat"><span>Model fitting</span><b>${num(result.timing.training_seconds,3)}s</b></div><div class="mini-stat"><span>Scoring + calibration</span><b>${num(result.timing.inference_seconds,3)}s</b></div><div class="mini-stat"><span>End-to-end analysis</span><b>${num(result.timing.total_seconds,3)}s</b></div><div class="mini-stat"><span>Runtime</span><b>Python ${esc(result.versions.python)}</b></div><div class="mini-stat"><span>scikit-learn</span><b>${esc(result.versions.sklearn)}</b></div><div class="notice">Browser and native Python timings are not interchangeable. Initial runtime download is excluded.</div>`)}</div><section class="card wide-card"><div class="card-head"><div><h2>Fixed vs adaptive windows</h2><p>Exploratory ablation · adaptive + 1, 5 and 10-minute fixed windows</p></div><button class="primary" data-action="compare">Run comparison ↗</button></div><div class="card-body">${comparison?`<div class="table-wrap"><table><thead><tr><th>STRATEGY</th><th>WINDOWS</th><th>PRECISION</th><th>RECALL</th><th>F1</th><th>TIME</th></tr></thead><tbody>${comparison.results.map(r=>`<tr><td>${r.mode==='adaptive'?'Adaptive':r.seconds/60+' min fixed'}</td>${r.error?`<td colspan="5">${esc(r.error)}</td>`:`<td>${r.summary.total_windows}</td><td>${pct(r.metrics?.precision)}</td><td>${pct(r.metrics?.recall)}</td><td>${r.metrics?.f1!=null?r.metrics.f1.toFixed(4):'—'}</td><td>${num(r.timing.total_seconds,2)}s</td>`}</tr>`).join('')}</tbody></table></div><p class="notice">${esc(comparison.note)}</p><button class="secondary" data-action="comparison">↓ Comparison JSON</button>`:'<p class="prose">Run all four strategies on the selected input. Scores and metrics are computed independently using training-only calibration. Different segmentation produces different evaluation units; this is not a controlled paper replication.</p>'}</div></section>`}
function render(){document.querySelectorAll('.nav').forEach(e=>e.classList.toggle('active',e.dataset.page===page));$('crumb').textContent=document.querySelector(`.nav[data-page="${page}"] span`).textContent;$('pageTitle').innerHTML=titles[page][0];$('pageSubtitle').textContent=titles[page][1];$('modeHint').textContent=$('mode').value+' segmentation';$('content').innerHTML=result?({overview,windows:windowsPage,incidents:incidentsPage,templates:templatesPage,evaluation:evaluationPage}[page])():'<div class="empty">Choose a dataset above, load its sample, then select Run analysis.</div>';updateResultTools();if(busy)setBusy(true)}
async function showWindow(id){await refreshTriage();const w=result.windows.find(w=>w.id===id);if(!w)return;$('dialogTitle').textContent=`Window ${id} · ${w.split}`;$('dialogBody').innerHTML=`<div class="prose"><p><span class="pill ${w.severity}">${w.severity}</span> &nbsp; ${esc(w.start)} → ${esc(w.end)}</p><p><b>Global score ${w.score.toFixed(4)}</b> / threshold ${result.summary.threshold.toFixed(4)}. Ground truth: ${w.label==null?'unknown':w.label?'anomaly':'normal'}.</p><h3>Supporting feature deviations</h3>${w.reasons.map(r=>`<p>• ${esc(r)}</p>`).join('')}<p class="caption">These statistical observations are not causal diagnoses or model feature attributions.</p><h3>Feature vector</h3></div><div class="detail-features">${Object.entries(w.features).map(([k,v])=>`<div>${esc(k)}<b>${num(v,4)}</b></div>`).join('')}</div><div class="prose"><h3>Partition scores</h3><pre>${esc(JSON.stringify(w.partition_scores,null,2))}</pre><h3>Example log messages</h3>${w.examples.map(e=>`<pre>${esc(e.level)} · ${esc(e.message)}\n\nTemplate: ${esc(e.template)}</pre>`).join('')}${w.anomaly&&w.split==='test'?`<h3>Incident triage</h3><div class="triage-form"><label>Status<select id="incidentStatus"><option value="open" ${incidentState(id).status==='open'?'selected':''}>Open</option><option value="acknowledged" ${incidentState(id).status==='acknowledged'?'selected':''}>Acknowledged</option><option value="resolved" ${incidentState(id).status==='resolved'?'selected':''}>Resolved</option></select></label><label>Owner<input id="incidentOwner" maxlength="100" value="${esc(incidentState(id).owner)}" placeholder="Analyst or team name"></label><label class="span-all">Investigation notes<textarea id="incidentNotes" maxlength="2000" rows="4" placeholder="Evidence reviewed, action taken, next step…">${esc(incidentState(id).notes)}</textarea></label><button class="primary" data-save-incident="${id}" data-version="${incidentState(id).version}">Save triage</button><span id="triageFeedback" role="status"></span></div><p class="caption">${backend&&result.run_id?'Saved to the configured Flask server with an audit trail.':'Saved in this browser. Export the incident CSV to share or retain a copy.'}</p>`:''}</div>`;$('detail').showModal()}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(v){let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
async function exportAction(action){if(busy)return;try{if(action==='report'){await refreshTriage();download(`${result.dataset}_client_report.html`,clientReport(),'text/html');return}if(action==='incidents'){await refreshTriage();exportIncidents();return}if(action==='json')download(`${result.dataset}_analysis.json`,JSON.stringify(result,null,2));if(action==='comparison')download('window_comparison.json',JSON.stringify(comparison,null,2));if(action==='csv'){const cols=['id','start','end','split','score','severity','label',...Object.keys(result.windows[0].features)];download(`${result.dataset}_window_features.csv`,[cols,...result.windows.map(w=>cols.map(c=>w[c]??w.features[c]??''))].map(row=>row.map(csvCell).join(',')).join('\n'),'text/csv')}if(action==='parsed'){setBusy(true);status('Preparing structured CSV…');let text;if(backend)text=await(await api('/api/parse',{text:inputText,dataset:$('dataset').value,labels:labelsText})).text();else text=await python('parse',payload('parse'));download('parsed_logs.csv',text,'text/csv');status('Parsed CSV exported.')}if(action==='model'){if(!runtimeModel)throw Error('Run a fresh analysis before exporting its trained model.');setBusy(true);if(backend){const b=await(await api('/api/runs/'+result.run_id+'/model')).arrayBuffer();download('logscope_model.joblib',b,'application/octet-stream')}else{const b=await python('model',{});download('logscope_model.joblib',Uint8Array.from(atob(b),c=>c.charCodeAt(0)),'application/octet-stream')}status('Model exported. Load only trusted joblib files.')}}catch(e){status(e.message,true)}finally{setBusy(false)}}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('logscope',1);r.onupgradeneeded=()=>r.result.createObjectStore('runs',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveHistory(value,id){if(backend)return true;try{const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('runs','readwrite');tx.objectStore('runs').put({id,date:new Date().toISOString(),dataset:value.dataset,result:value});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});d.close();return true}catch(e){return false}}
async function showHistory(){try{let items;if(backend)items=await(await api('/api/runs')).json();else{const d=await db();items=await new Promise((resolve,reject)=>{const r=d.transaction('runs').objectStore('runs').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});d.close();items.reverse()}$('dialogTitle').textContent='Saved run history';$('dialogBody').innerHTML=items.length?`<p class="tab-note">Restore results for inspection and export. To rerun or compare, select the original input file again.</p>${items.map(r=>`<div class="mini-stat"><span>${esc(r.dataset)} · ${esc(r.date||r.created)}</span><button class="link-button" data-restore="${esc(r.id)}">Open result →</button></div>`).join('')}`:'<div class="empty">No saved runs yet. Run a fresh analysis to save one.</div>';$('detail').showModal()}catch(e){status(e.message,true)}}
async function restore(id){if(busy)return;try{if(backend)result=await(await api('/api/runs/'+id)).json();else{const d=await db();result=await new Promise((resolve,reject)=>{const r=d.transaction('runs').objectStore('runs').get(id);r.onsuccess=()=>resolve(r.result.result);r.onerror=()=>reject(r.error)});d.close()}runtimeModel=backend;currentRunKey=id;comparison=null;source='history';inputKind='restored';inputName=result.client?.input_name||'Restored result';$('dataset').value=result.dataset;applyConfig(result.config);inputText='';labelsText='';$('fileName').textContent='Restored result · load a sample to rerun';$('detail').close();$('provenance').textContent='Restored saved run · '+result.dataset;await refreshTriage();render()}catch(e){status(e.message,true)}}
async function loadSample(){if(busy)return;setBusy(true);const dataset=$('dataset').value;const original=dataset==='OpenStack'&&$('sampleProfile').value==='original';$('sampleProfileLabel').classList.toggle('hidden',dataset!=='OpenStack');const rawPath=dataset==='OpenStack'&&!original?'OpenStack_labeled.log':`${dataset}_2k.log`;const resultPath=original?'OpenStack_2k_result.json':`${dataset}_result.json`;try{const [raw,res]=await Promise.all([fetch(`data/${rawPath}`,{cache:'no-store'}),fetch(`data/${resultPath}`,{cache:'no-store'})]);if(!raw.ok||!res.ok)throw Error('Sample files could not be loaded.');inputText=await raw.text();inputName=rawPath;inputKind='sample';result=await res.json();applyConfig(result.config);labelsText='';$('labels').value='';$('fileName').textContent=rawPath+' · official LogHub data';$('inputStatus').textContent=`${num(result.summary.total_logs)} logs · ${result.evaluation?.provenance?.label_kind==='derived_vm_association'?'derived VM-association labels':'matching annotation labels auto-loaded'}`;comparison=null;runtimeModel=false;source='sample';triageCache={};currentRunKey='sample-'+dataset+(original?'-original':'');pageIndex=0;$('provenance').textContent=`Measured result · ${dataset} · ${result.evaluation?.provenance?.label_kind||'input labels'} · Run analysis to recompute`;$('status').className='status hidden';await refreshTriage();render()}catch(e){status(e.message,true)}finally{setBusy(false)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page||b.dataset.nav){page=b.dataset.page||b.dataset.nav;render()}if(b.dataset.window)showWindow(+b.dataset.window).catch(err=>status(err.message,true));if(b.dataset.restore)restore(b.dataset.restore);if(b.dataset.saveIncident)saveIncident(+b.dataset.saveIncident,+b.dataset.version);const a=b.dataset.action;if(a==='incidentPrev'||a==='incidentNext'){incidentPage+=a==='incidentNext'?1:-1;render()}else if(a==='compare')execute('compare');else if(a==='prev'||a==='next'){pageIndex+=a==='next'?1:-1;render()}else if(a)exportAction(a)});
document.addEventListener('change',e=>{if(e.target.id==='windowFilter'){filter=e.target.value;pageIndex=0;render()}if(e.target.id==='incidentFilter'){incidentFilter=e.target.value;incidentPage=0;render()}});
document.addEventListener('input',e=>{if(e.target.id==='windowSearch'){search=e.target.value;const pos=e.target.selectionStart;pageIndex=0;render();$('windowSearch').focus();$('windowSearch').setSelectionRange(pos,pos)}});
$('runBtn').onclick=()=>execute('analyze');$('sampleBtn').onclick=loadSample;$('dataset').onchange=()=>{if(inputKind==='upload'){result=null;comparison=null;runtimeModel=false;$('sampleProfileLabel').classList.add('hidden');$('inputStatus').textContent='Uploaded file preserved · parser changed to '+$('dataset').value;render()}else{$('sampleProfile').value='annotated';loadSample()}};$('sampleProfile').onchange=loadSample;$('historyBtn').onclick=showHistory;$('closeDialog').onclick=()=>$('detail').close();$('settingsBtn').onclick=()=>{const hidden=$('settings').classList.toggle('hidden');$('settingsBtn').setAttribute('aria-expanded',String(!hidden))};$('mode').onchange=()=>{$('modeHint').textContent=$('mode').value+' segmentation'};
$('labels').onchange=async()=>{const f=$('labels').files[0];if(!f)return;try{if(!/\.csv$/i.test(f.name)||!f.size||f.size>3*1024*1024)throw Error('Labels must be a nonempty CSV no larger than 3 MB.');const text=await f.text();if(!text.trim()||text.includes('\0'))throw Error('Choose a UTF-8 label CSV.');labelsText=text;status('Labels selected: '+f.name+'. Run analysis to apply them. Existing results are unchanged.')}catch(e){$('labels').value='';labelsText='';status(e.message,true)}};
$('clearLabels').onclick=()=>{labelsText='';$('labels').value='';status('External labels cleared. Exact-matching bundled annotations still apply. Run analysis to update results.')};
$('cancelBtn').onclick=()=>{worker?.terminate();worker=null;for(const p of waiting.values())p.reject(Error('Analysis cancelled.'));waiting.clear();runtimeModel=false;setBusy(false)};
(async()=>{try{const r=await fetch('/api/health');if(r.ok&&r.headers.get('content-type')?.includes('application/json')){const h=await r.json();backend=h.runtime==='flask'}}catch{}$('runtimeBadge').textContent=backend?'Server analysis':'On-device analysis';$('connectionBtn').classList.toggle('hidden',!backend);await loadSample()})();

function applyConfig(c){if(!c)return;const ids={mode:'mode',fixed_seconds:'fixedSeconds',min_seconds:'minSeconds',max_seconds:'maxSeconds',target_logs:'targetLogs',train_fraction:'trainFraction',contamination:'contamination',trees:'trees',partitions:'partitions'};for(const [key,id] of Object.entries(ids))if(c[key]!=null)$(id).value=c[key]}
function updateResultTools(){const has=!!result;$('resultTools').classList.toggle('hidden',!has);if(!has)return;const prefix=source==='sample'?'Sample result':source==='history'?'Saved result':'Analysis complete';$('resultContext').textContent=`${prefix} · ${result.dataset} · ${num(result.summary.total_logs)} logs`;$('storageContext').textContent=backend&&result.run_id?'Analysis and triage are stored on your configured server.':'Analysis stays on this device. Browser storage is not a backup—export results you need to retain.'}
function localJSON(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch{return fallback}}
function incidentState(id){const stored=triageCache[String(id)];if(stored)return {...{status:'open',notes:'',owner:'',updated:'',version:0},...stored};let legacy='open';try{legacy=localStorage.getItem('incident:'+currentRunKey+':'+id)||'open'}catch{}return {status:legacy,notes:'',owner:'',updated:'',version:0}}
async function refreshTriage(){if(!currentRunKey){triageCache={};return}if(backend&&result?.run_id){try{triageCache=await(await api('/api/runs/'+result.run_id+'/triage')).json()}catch(e){status(e.message,true);throw e}}else triageCache=localJSON('triage:'+currentRunKey,{})}
function incidentsPage(){const all=testWindows().filter(w=>w.anomaly),counts={open:0,acknowledged:0,resolved:0};for(const w of all)counts[incidentState(w.id).status]=(counts[incidentState(w.id).status]||0)+1;const filtered=all.filter(w=>incidentFilter==='all'||incidentState(w.id).status===incidentFilter).sort((a,b)=>b.score-a.score);incidentPage=Math.max(0,Math.min(incidentPage,Math.ceil(filtered.length/20)-1));return `<div class="metrics">${metric('Flagged test windows',num(all.length),'Candidates for human review','⚑')}${metric('Open',num(counts.open),'Awaiting investigation','◷')}${metric('Acknowledged',num(counts.acknowledged),'Investigation in progress','↗')}${metric('Resolved',num(counts.resolved),'Disposition recorded','✓')}</div><section class="card"><div class="card-head"><div><h2>Incident worklist</h2><p>These are model-flagged windows, not confirmed incidents.</p></div><button class="secondary" data-action="incidents">↓ Incident CSV</button></div><div class="filters"><label>Show status<select id="incidentFilter">${['all','open','acknowledged','resolved'].map(v=>`<option value="${v}" ${v===incidentFilter?'selected':''}>${v==='all'?'All statuses':v}</option>`).join('')}</select></label></div><div class="table-wrap"><table><thead><tr><th>WINDOW / UTC</th><th>SEVERITY</th><th>STATUS</th><th>OWNER</th><th>NOTES</th><th></th></tr></thead><tbody>${filtered.slice(incidentPage*20,(incidentPage+1)*20).map(w=>{const t=incidentState(w.id);return `<tr><td><b>W${w.id}</b><br><span class="mono">${esc(w.start)}</span></td><td><span class="pill ${w.severity}">${esc(w.severity)}</span></td><td>${esc(t.status)}</td><td>${esc(t.owner||'Unassigned')}</td><td>${esc(t.notes.slice(0,100)||'No notes yet')}${t.notes.length>100?'…':''}</td><td><button class="link-button" data-window="${w.id}">Review ↗</button></td></tr>`}).join('')}</tbody></table></div>${!filtered.length?'<div class="empty">No flagged windows match this status.</div>':''}<div class="pager"><span>${num(filtered.length)} matching windows</span><div class="exports"><button class="secondary" data-action="incidentPrev" ${!incidentPage?'disabled':''}>← Previous</button><button class="secondary" data-action="incidentNext" ${(incidentPage+1)*20>=filtered.length?'disabled':''}>Next →</button></div></div></section>`}
async function saveIncident(id,version){const btn=document.querySelector('[data-save-incident]'),feedback=$('triageFeedback');if(btn)btn.disabled=true;try{const next={status:$('incidentStatus').value,owner:$('incidentOwner').value.trim(),notes:$('incidentNotes').value.trim(),expected_version:version};let saved;if(backend&&result.run_id){saved=await(await api(`/api/runs/${result.run_id}/incidents/${id}`,next)).json()}else{const latest=localJSON('triage:'+currentRunKey,{});const current=latest[String(id)]||{version:0};if(current.version!==version)throw Error('This incident changed in another tab. Reopen it before saving.');saved={status:next.status,owner:next.owner,notes:next.notes,updated:new Date().toISOString(),version:version+1};latest[String(id)]=saved;localStorage.setItem('triage:'+currentRunKey,JSON.stringify(latest))}triageCache[String(id)]=saved;if(btn)btn.dataset.version=String(saved.version);feedback.textContent='Saved '+new Date(saved.updated).toLocaleTimeString();render()}catch(e){feedback.textContent=e.message;status(e.message,true)}finally{if(btn)btn.disabled=false}}
function exportIncidents(){const rows=[['window_id','start_utc','severity','score','status','owner','notes','updated_utc'],...testWindows().filter(w=>w.anomaly).map(w=>{const t=incidentState(w.id);return [w.id,w.start,w.severity,w.score,t.status,t.owner,t.notes,t.updated]})];download(`${result.dataset}_incidents.csv`,rows.map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv')}
function clientReport(){const r=result,s=r.summary,m=r.metrics,ev=r.evaluation,alerts=testWindows().filter(w=>w.anomaly).sort((a,b)=>b.score-a.score),value=v=>v==null?'Unavailable':Number(v).toFixed(4);const generated=new Date().toISOString();return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LogScope report — ${esc(r.dataset)}</title><style>body{font:14px/1.6 system-ui,sans-serif;color:#18332c;max-width:1000px;margin:40px auto;padding:0 30px}header{border-bottom:3px solid #176b57;padding-bottom:20px}h1{font-size:32px}h2{font-size:20px;margin-top:30px}small,.muted{color:#62756b}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.kpis div{border:1px solid #dbe5dd;padding:16px;border-radius:6px}.kpis b{display:block;font-size:27px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;border-bottom:1px solid #dbe5dd;padding:9px;overflow-wrap:anywhere}th{background:#f1f5ee}.notice{background:#f4f6e9;border-left:4px solid #819458;padding:16px}svg{width:100%;height:auto}.chart-label{fill:#65766b;font:10px system-ui}footer{margin-top:30px;border-top:1px solid #ddd;padding-top:15px}section{break-inside:avoid}@media print{body{margin:0;max-width:none;padding:0}.print-hint{display:none}thead{display:table-header-group}tr{break-inside:avoid}h2{break-after:avoid}}@media(max-width:600px){.kpis{grid-template-columns:1fr 1fr}}</style></head><body><header><small>LOGSCOPE / CLIENT EVALUATION 1.1.0</small><h1>Log analysis report</h1><p><b>${esc(r.dataset)}</b> · ${esc(r.client?.input_name||inputName||'Bundled sample')}</p><small>Generated ${esc(generated)} · Run ${esc(r.run_id||currentRunKey)}<br>Input period ${esc(s.start)} to ${esc(s.end)}</small><p class="print-hint">Use your browser’s Print command to print or save this report as PDF.</p></header><div class="kpis"><div>Logs processed<b>${num(s.total_logs)}</b></div><div>Test windows<b>${num(s.test_windows)}</b></div><div>Flagged test windows<b>${num(s.anomalous_windows)}</b></div><div>Rejected rows<b>${num(r.quality.rejected_rows)}</b></div></div><section><h2>Decision context</h2><p>This batch analysis identifies unusual log windows for human investigation. Scores are not failure probabilities. Severity is a project-defined rule; statistical explanations do not establish root cause.</p><div class="notice">${esc(ev?.provenance?.note||'Label provenance unavailable.')} ${m?.single_class?'Only one label class appears in the test interval; classification metrics have limited applicability.':''}</div></section><section><h2>Held-out evaluation</h2><table><thead><tr><th>Precision</th><th>Recall</th><th>F1</th><th>Accuracy</th><th>False-positive rate</th></tr></thead><tbody><tr><td>${value(m?.precision)}</td><td>${value(m?.recall)}</td><td>${value(m?.f1)}</td><td>${value(m?.accuracy)}</td><td>${value(m?.fpr)}</td></tr></tbody></table><p>Labels available: ${num(r.quality.labels_available)} / ${num(s.total_logs)} logs.${m?` Confusion counts: TP ${m.tp}, TN ${m.tn}, FP ${m.fp}, FN ${m.fn}.`:''}</p></section><section><h2>Anomaly signal</h2>${curve(testWindows(),'score',s.threshold)}<p class="muted">Held-out windows only. Dashed line: training-derived threshold ${s.threshold.toFixed(4)}.</p></section><h2>Priority review — top 20</h2><table><thead><tr><th>Window / UTC</th><th>Score / severity</th><th>Status / owner</th><th>Evidence and notes</th></tr></thead><tbody>${alerts.slice(0,20).map(w=>{const t=incidentState(w.id);return `<tr><td>W${w.id}<br>${esc(w.start)}</td><td>${w.score.toFixed(4)}<br>${esc(w.severity)}</td><td>${esc(t.status)}<br>${esc(t.owner||'Unassigned')}</td><td>${esc(w.reasons.join('; '))}<br><b>Notes:</b> ${esc(t.notes||'None')}</td></tr>`}).join('')}</tbody></table>${!alerts.length?'<p>No test windows exceed the configured threshold.</p>':''}<p class="muted">Export Incident CSV for the complete worklist. This report excludes raw log messages.</p><section><h2>Configuration and reproducibility</h2><table><tbody>${Object.entries(r.config).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table><p>Python ${esc(r.versions.python)} · scikit-learn ${esc(r.versions.sklearn)} · NumPy ${esc(r.versions.numpy)}. Analysis time: ${num(r.timing.total_seconds,3)} seconds.</p></section><section><h2>Limitations and follow-up</h2><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><p>Validate suspicious windows against operational evidence. Measure accuracy on representative client data before using this software for unattended alerting. This release does not include production live ingestion, external notifications or multi-machine execution.</p></section><footer>Generated locally by LogScope. Keep the accompanying Results JSON for reproducibility and exact feature values.</footer></body></html>`}
$('connectionBtn').onclick=()=>{$('dialogTitle').textContent='Server access';$('dialogBody').innerHTML='<p class="prose">If your administrator configured an API token, enter it here. It is stored in this tab’s session storage and sent only to this application’s API.</p><label>API token<input id="apiToken" type="password" autocomplete="off" class="full-input"></label><p><button class="primary" id="saveApiToken">Use token</button> <button class="secondary" id="clearApiToken">Clear token</button></p>';$('detail').showModal();$('saveApiToken').onclick=()=>{sessionStorage.setItem('logscope-token',$('apiToken').value.trim());$('apiToken').value='';$('detail').close();status('Server access token saved for this tab. Retry the requested action.')};$('clearApiToken').onclick=()=>{sessionStorage.removeItem('logscope-token');$('detail').close();status('Server access token cleared.')};};
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue=''}});
